{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "Pravastatin has an absolute oral bioavailability of 0.18 (18%) in humans, below the 20% threshold; as a statin with the same dihydroxyheptanoic acid side chain, it demonstrates that this chemotype can undergo extensive first-pass metabolism leading to F<20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Pravastatin's absolute bioavailability is 18%, attributed to incomplete absorption and hepatic first-pass metabolism; this mechanism is relevant to the query's large lipophilic statin structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Fluvastatin, the closest structural analogue, has F=24% in patients, above threshold; however, the query contains additional bulky anilide and phenyl substituents that increase molecular weight and lipophilicity, likely increasing hepatic extraction and lowering F relative to fluvastatin.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C12"],
      "claim": "Cerivastatin has absolute F=60%, but its smaller, less lipophilic structure and lower first-pass extraction limit transferability to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C02"],
      "claim": "Rosuvastatin has F≈20%, at the threshold; this is not affirmative evidence for low bioavailability and is outweighed by the query's higher lipophilicity and first-pass liability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is recognized as atorvastatin, a large lipophilic statin with an established absolute oral bioavailability around 14%, below the 20% threshold. The statin evidence, especially pravastatin's low F due to first-pass metabolism, supports a low-F pattern; the higher F values of fluvastatin and cerivastatin are less transferable because the query's additional bulky lipophilic substituents increase first-pass extraction.",
  "evidence_gaps": [
    "No direct atorvastatin absolute bioavailability record is present in the supplied evidence set; the closest analogue (fluvastatin) is above threshold, so the low prediction relies on structural reasoning and known first-pass metabolism of the statin class.",
    "No data on active metabolites, which contribute to statin pharmacology but not parent F."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

